const classRows = $input.all().map((item) => item.json || {}).filter((row) => row.id);
const snapshotDate = $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');
return [{
  json: {
    class_ids: classRows.map((row) => row.id),
    class_rows: classRows,
    snapshot_date: snapshotDate,
  },
}];

const prepared = $('Prepare Climate Snapshot Batch').first().json || {};
const classRows = Array.isArray(prepared.class_rows) ? prepared.class_rows : [];
const classMap = new Map(classRows.map((row) => [row.id, row]));
const snapshot = $json || {};
const classMeta = classMap.get(snapshot.class_id) || {};
const totalResponses = Number(snapshot.total_responses || 0);
const isSafe = snapshot.k_anonymity_safe === true || snapshot.avg_mood_score != null;
return {
  json: {
    class_id: snapshot.class_id || classMeta.id || null,
    class_name: classMeta.name || null,
    teacher_id: classMeta.teacher_id || null,
    avg_mood_score: snapshot.avg_mood_score ?? null,
    avg_pace_score: snapshot.avg_pace_score ?? null,
    avg_fairness_score: snapshot.avg_fairness_score ?? null,
    total_responses: totalResponses,
    k_anonymity_safe: isSafe,
    blocked_reason: snapshot.blocked_reason || (isSafe ? null : totalResponses > 0 ? 'k_anonymity' : 'no_responses'),
    snapshot_date: snapshot.snapshot_date || prepared.snapshot_date || null,
  },
};

const item = $json || {};
const blockedReason = item.blocked_reason || 'k_anonymity';
return {
  json: {
    ...item,
    blocked_reason: blockedReason,
    decision_path_json: {
      route: 'blocked_by_k_anonymity',
      blocked_reason: blockedReason,
      snapshot_date: item.snapshot_date || null,
    },
  },
};

let metrics = {};
try { metrics = $('Tool: Get Teacher Metrics').item.json || {}; } catch(e){}
let summary = {};
try { summary = $("Call 'Tool: Get Past Recommendations'").item.json || {}; } catch(e){}
let climate = {};
try { climate = $('Get Aggregated Climate Data').item.json || {}; } catch(e){}

let avg_mood = (metrics.avg_mood_score !== undefined && metrics.avg_mood_score !== null)
  ? metrics.avg_mood_score
  : (climate.avg_mood_score !== undefined && climate.avg_mood_score !== null)
    ? climate.avg_mood_score
    : $input.item.json.avg_mood_score;

return {
  json: {
    ...climate,
    ...$input.item.json,
    teacher_metrics: metrics,
    past_summary: summary,
    avg_mood_score: avg_mood
  }
};

const item = $json || {};
const metrics = item.teacher_metrics || {};
const summary = item.past_summary || {};
const comparison = item.trend_comparison || item.trend || {};
const closureHistory = item.closure_history || {};
const redactedVoice = String(item.redacted_voice_summary || item.redacted_voice || '').trim();
const blockedReason = item.blocked_reason || item.skip_reason || 'none';
const avgMood = Number(item.avg_mood_score ?? metrics.avg_mood_score ?? 3.5);
const avgPace = Number(item.avg_pace_score ?? item.avg_pace ?? 3);
const avgFairness = Number(item.avg_fairness_score ?? item.avg_fairness ?? 3);
const totalResponses = Number(item.total_responses ?? 0);
const dismissalRate = Number(metrics.dismissal_rate ?? summary.dismissal_rate ?? 0);
const consecutiveDismissals = Number(metrics.dismissal_pattern_consecutive ?? 0);
const inquiryModeSuggested =
  metrics.inquiry_mode_suggested === true ||
  metrics.teacher_flag_inquiry_mode === true ||
  metrics.is_inquiry_mode === true;

const compactContext = {
  class_id: item.class_id || 'unknown',
  class_name: item.class_name || item.room_name || 'unknown',
  avg_mood: Number.isFinite(avgMood) ? Number(avgMood.toFixed(2)) : null,
  avg_pace: Number.isFinite(avgPace) ? Number(avgPace.toFixed(2)) : null,
  avg_fairness: Number.isFinite(avgFairness) ? Number(avgFairness.toFixed(2)) : null,
  total_responses: totalResponses,
  blocked_reason: blockedReason,
  preview_policy: item.fast_path_preview_policy || 'unknown',
  dismissal_rate: Number.isFinite(dismissalRate) ? Number(dismissalRate.toFixed(2)) : 0,
  consecutive_dismissals: consecutiveDismissals,
  inquiry_mode_suggested: inquiryModeSuggested,
  latest_approved_summary: String(summary.summary_text || summary.reasoning || 'none').slice(0, 120),
  trend: (typeof comparison === 'object' ? JSON.stringify(comparison) : String(comparison || 'none')).slice(0, 120),
  redacted_voice: redactedVoice.slice(0, 120) || 'none',
  closure_history: JSON.stringify(closureHistory).slice(0, 120),
};

const prompt = [
  'คุณคือผู้ช่วยวิเคราะห์ climate ห้องเรียนแบบ privacy-safe',
  'ใช้เฉพาะข้อมูล aggregate และข้อมูลที่ผ่านการ redaction แล้ว ห้ามกล่าวถึงนักเรียนรายบุคคล',
  `บริบท: ${JSON.stringify(compactContext)}`,
  'งานของคุณ:',
  '- สรุปสถานการณ์ให้ครูแบบกระชับและตรงประเด็น',
  '- ถ้าควรเก็บบริบทเพิ่ม ให้ structuredPayload.mode เป็น inquiry และ studentMessageDraft เป็น null',
  '- ถ้าไม่มั่นใจพอ ให้ confidence_score ต่ำกว่า 0.65',
  'ตอบ JSON เท่านั้น:',
  '{"policy_level":"ROUTINE|WARNING|CRITICAL","confidence_score":0.0,"recommendation_content":"ข้อความสรุปสั้นสำหรับครู","reasoning":"คำอธิบายสั้นว่าทำไมข้อเสนอนี้จึงเหมาะตอนนี้","actions_json":["แผนสั้นข้อ 1"],"inquiry_mode":false,"fallback_used":false,"structuredPayload":{"version":1,"mode":"action|inquiry","source":"llm","teacherSummary":"...","situationHypothesis":"...","recommendedTeacherMove":"...","studentMessageDraft":"... or null","teacherActionPlan":["..."],"watchSignals":["..."],"whyThisHelps":"...","postClassReflectionPrompt":"... or null"}}',
].join('\n');

return {
  json: {
    ...item,
    llm_prompt: prompt,
    llm_provider: 'ollama',
    llm_model: 'qwen2.5:3b',
  },
};

const source = $('Build Ollama Analysis Prompt').first().json || $('Merge Metrics Into Item').first().json || {};
const normalizePolicy = (value) => {
  const text = String(value || '').trim().toUpperCase();
  return ['ROUTINE', 'WARNING', 'CRITICAL'].includes(text) ? text : null;
};
const coerceConfidence = (value) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0;
  return Math.max(0, Math.min(1, numeric));
};
const rawOutput = typeof $json.text === 'string' ? $json.text : typeof $json.output === 'string' ? $json.output : typeof $json.response?.text === 'string' ? $json.response.text : JSON.stringify($json || {});
let parsed;
try { parsed = JSON.parse(rawOutput.replace(/```json/g, '').replace(/```/g, '').trim()); } catch (error) { parsed = null; }
const policyLevel = normalizePolicy(parsed?.policy_level);
const confidenceScore = coerceConfidence(parsed?.confidence_score);
const recommendationContent = typeof parsed?.recommendation_content === 'string' ? parsed.recommendation_content.replace(/\s+/g, ' ').trim() : '';
const reasoning = typeof parsed?.reasoning === 'string' ? parsed.reasoning.replace(/\s+/g, ' ').trim().slice(0, 500) : '';
const actions = Array.isArray(parsed?.actions_json) ? parsed.actions_json : [];
const structuredPayload = parsed?.structuredPayload && typeof parsed.structuredPayload === 'object' && !Array.isArray(parsed.structuredPayload) ? parsed.structuredPayload : null;
const requiredStructuredFields = structuredPayload && structuredPayload.version === 1 && ['teacherSummary','situationHypothesis','recommendedTeacherMove','teacherActionPlan','watchSignals','whyThisHelps'].every((key) => structuredPayload[key]);
const studentMessageDraft = typeof structuredPayload?.studentMessageDraft === 'string' ? structuredPayload.studentMessageDraft.replace(/\s+/g, ' ').trim() : '';
const teacherPlan = Array.isArray(structuredPayload?.teacherActionPlan) ? structuredPayload.teacherActionPlan : actions;
if (!policyLevel || !recommendationContent || !reasoning || !requiredStructuredFields || confidenceScore < 0.65) {
  return {
    json: {
      ...source,
      policy_level: policyLevel,
      confidence_score: confidenceScore,
      recommendation_content: recommendationContent,
      ai_message_draft: studentMessageDraft || recommendationContent,
      reasoning: reasoning || 'parser_rejected_output',
      actions_json: teacherPlan,
      inquiry_mode: structuredPayload?.mode === 'inquiry',
      fallback_used: false,
      ai_attempted: true,
      ai_fallback_reason: !requiredStructuredFields ? 'structured_payload_invalid' : confidenceScore < 0.65 ? 'low_confidence' : 'parser_rejected_output',
      decision_path: { route: 'parser_rejected', generated_by: 'ollama', llm_output_rejected: true },
    },
  };
}
return {
  json: {
    ...source,
    policy_level: policyLevel,
    confidence_score: confidenceScore,
    recommendation_content: recommendationContent,
    ai_message_draft: studentMessageDraft || recommendationContent,
    reasoning,
    actions_json: teacherPlan,
    inquiry_mode: structuredPayload.mode === 'inquiry',
    fallback_used: false,
    ai_attempted: true,
    ai_fallback_reason: null,
    structuredPayload: { ...structuredPayload, version: 1, source: 'llm' },
    decision_path: { route: 'ai', generated_by: 'ollama', llm_output_rejected: false },
  },
};

const metrics = $json.teacher_metrics || {};
const summary = $json.past_summary || {};
const avgMood = Number($json.avg_mood_score ?? metrics.avg_mood_score ?? 3.5);
const avgPace = Number($json.avg_pace_score ?? $json.avg_pace ?? 3);
const avgFairness = Number($json.avg_fairness_score ?? $json.avg_fairness ?? 3);
const dismissalRate = Number(metrics.dismissal_rate ?? summary.dismissal_rate ?? 0);
const consecutiveDismissals = Number(metrics.dismissal_pattern_consecutive ?? 0);
const teacherFlagInquiryMode = metrics.teacher_flag_inquiry_mode === true || metrics.is_inquiry_mode === true;
const recentNoAction = Number(metrics.dismissed_count ?? 0) >= 2 || dismissalRate > 0.6;
const aiAttempted = $json.ai_attempted === true;
const aiFallbackReason = $json.ai_fallback_reason || null;
const fastPathReason = $json.fast_path_reason || null;

let policyLevel = 'ROUTINE';
if (avgMood <= 2.0) policyLevel = 'CRITICAL';
else if (avgMood <= 3.0) policyLevel = 'WARNING';

const inquiryMode =
  teacherFlagInquiryMode ||
  (dismissalRate > 0.6 && consecutiveDismissals >= 2 && ['WARNING', 'CRITICAL'].includes(policyLevel));

let teacherSummary = 'ภาพรวมของห้องยังอยู่ในเกณฑ์ที่พอไปได้ และควรรักษาจังหวะที่ช่วยให้เด็กมีส่วนร่วมต่อเนื่อง';
let situationHypothesis = 'ห้องยังไม่เห็นสัญญาณที่ต้องแก้เฉพาะจุดแบบเร่งด่วน';
let recommendedTeacherMove = 'ชวนสะท้อนสิ่งที่ทำได้ดีสั้น ๆ ก่อนเริ่มกิจกรรมถัดไป';
let studentMessageDraft = 'ขอบคุณสำหรับฟีดแบ็กของห้อง วันนี้เราจะคงจังหวะคาบที่ช่วยให้ทุกคนตามทัน และถ้ามีจุดไหนยังติดสามารถบอกได้เลย';
let teacherActionPlan = ['ชวนห้องสะท้อนสิ่งที่ทำได้ดีสั้น ๆ', 'รักษาจังหวะคาบที่ช่วยให้ห้องมีส่วนร่วม'];
let watchSignals = ['ห้องยังมีส่วนร่วมสม่ำเสมอหรือไม่', 'นักเรียนเริ่มถามมากขึ้นหรือไม่'];
let whyThisHelps = 'การรักษาจังหวะที่ห้องรับได้ดีจะช่วยคงบรรยากาศให้เสถียรต่อเนื่อง';
let postClassReflectionPrompt = 'หลังคาบนี้ เด็กตอบสนองอย่างไร และมีจุดไหนที่ควรปรับต่อ';

if (inquiryMode) {
  teacherSummary = 'สัญญาณรวมของห้องเริ่มอ่อนลง แต่ยังควรเก็บบริบทจากครูเพิ่มก่อนตัดสินใจส่งข้อความถึงนักเรียน';
  situationHypothesis = 'ข้อมูลรวมบอกว่าห้องมีแรงตึงบางช่วง แต่ยังไม่พอจะชี้ว่าควรแก้ตรงไหนก่อน';
  recommendedTeacherMove = 'เติมบริบทสั้น ๆ ว่าปัญหาน่าจะเกิดช่วงไหนของคาบ';
  studentMessageDraft = null;
  teacherActionPlan = [
    'เติมบริบทสั้น ๆ ว่าปัญหาน่าจะเกิดช่วงไหนของคาบ',
    'บอกระบบว่าคุณครูอยากให้ช่วยต่อเรื่องใด',
    'ค่อยตัดสินใจอีกครั้งหลังได้บริบทเพิ่ม',
  ];
  watchSignals = [
    'ช่วงที่เด็กเริ่มเงียบพร้อมกัน',
    'กิจกรรมที่ทำให้เด็กถามน้อยลง',
    'จังหวะที่ครูรู้สึกว่าห้องเริ่มหลุดจากการมีส่วนร่วม',
  ];
  whyThisHelps = 'การเติมบริบทจากครูก่อนจะช่วยให้ข้อเสนอรอบถัดไปตรงกับสถานการณ์จริงของห้องมากขึ้น';
  postClassReflectionPrompt = null;
} else if (avgMood <= 2 && avgPace <= 2.5) {
  teacherSummary = 'บรรยากาศของห้องอ่อนลงชัด และมีแนวโน้มว่าช่วงต้นคาบอาจหนักหรือเร็วเกินไป';
  situationHypothesis = 'นักเรียนบางส่วนอาจยังตั้งหลักกับเนื้อหาไม่ทัน จึงเงียบลงและมีส่วนร่วมน้อยลง';
  recommendedTeacherMove = 'เริ่มคาบถัดไปด้วยการเช็กอินสั้น ๆ แล้วผ่อนจังหวะช่วงแรกของคาบ';
  studentMessageDraft = 'จากฟีดแบ็กของห้อง วันนี้เราจะเริ่มคาบด้วยช่วงเช็กอินสั้น ๆ และค่อย ๆ ปรับจังหวะให้ทุกคนตามทันมากขึ้น ถ้ายังมีจุดไหนติดอยู่สามารถบอกได้เลย';
  teacherActionPlan = [
    'เปิดช่วงคุยสั้น ๆ 3-5 นาที ก่อนเริ่มเนื้อหาใหม่',
    'เช็กว่านักเรียนติดตรงไหนหรือกังวลเรื่องใดมากที่สุด',
    'ลดความหนาแน่นของช่วงต้นคาบลงเล็กน้อย',
  ];
  watchSignals = [
    'นักเรียนเริ่มตอบหรือถามมากขึ้นหลังเช็กอิน',
    'บรรยากาศช่วงต้นคาบผ่อนลงหรือไม่',
    'คำถามเดิมยังกลับมาซ้ำในคาบถัดไปหรือไม่',
  ];
  whyThisHelps = 'ถ้าปัญหาเกิดจากความตึงในช่วงต้นคาบ การเปิดพื้นที่พูดและผ่อนจังหวะก่อนจะช่วยลดแรงกดดันและทำให้เด็กกลับมามีส่วนร่วมง่ายขึ้น';
} else if (avgMood <= 2.5 && avgFairness <= 2.7) {
  teacherSummary = 'ห้องนี้มีทั้งสัญญาณความรู้สึกต่ำและความรู้สึกว่าโอกาสหรือความชัดเจนอาจยังไม่เท่ากัน';
  situationHypothesis = 'นักเรียนบางส่วนอาจไม่มั่นใจว่าตัวเองตามทันหรือมีพื้นที่ถามได้มากพอ';
  recommendedTeacherMove = 'เปิดพื้นที่คุยสั้น ๆ และสื่อสาร expectation ให้ชัดขึ้นก่อนเริ่มกิจกรรมหลัก';
  studentMessageDraft = 'จากฟีดแบ็กของห้อง คาบถัดไปเราจะเริ่มด้วยการเช็กว่ามีจุดไหนยังไม่ชัด และจะอธิบายความคาดหวังของคาบให้ชัดขึ้น เพื่อให้ทุกคนตามได้มากขึ้น';
  teacherActionPlan = [
    'เปิดพื้นที่ให้ถามแบบสั้น ๆ ก่อนเริ่มโจทย์หลัก',
    'ย้ำ expectation และเกณฑ์ของกิจกรรมให้ชัด',
    'เช็กว่ามีนักเรียนกลุ่มไหนยังรู้สึกตามไม่ทัน',
  ];
  watchSignals = [
    'เด็กกล้าถามมากขึ้นหรือไม่',
    'คำถามซ้ำเรื่องเกณฑ์ลดลงหรือไม่',
    'บรรยากาศห้องผ่อนลงหลังสื่อสาร expectation ชัดขึ้นหรือไม่',
  ];
  whyThisHelps = 'เมื่อเด็กเห็นภาพคาดหวังชัดและรู้ว่าถามได้ง่ายขึ้น ความตึงจากความไม่แน่ใจจะลดลง';
} else if (avgPace <= 2.5) {
  teacherSummary = 'สัญญาณหลักของห้องอยู่ที่จังหวะคาบที่เริ่มฝืดหรือหนักเกินไปในบางช่วง';
  situationHypothesis = 'เด็กอาจยังรับช่วงต้นคาบไม่ทัน ทำให้การมีส่วนร่วมค่อย ๆ ลดลง';
  recommendedTeacherMove = 'ชะลอช่วงต้นคาบลงเล็กน้อยและเพิ่ม checkpoint สั้น ๆ';
  studentMessageDraft = 'คาบถัดไปเราจะค่อย ๆ ปรับจังหวะช่วงต้นคาบให้ชัดและช้าลงขึ้นนิดหนึ่ง และจะมีจุดเช็กความเข้าใจสั้น ๆ ระหว่างทาง';
  teacherActionPlan = [
    'ชะลอช่วงต้นคาบลงเล็กน้อย',
    'เพิ่ม checkpoint สั้น ๆ ระหว่างคาบ',
    'เช็กจุดที่เด็กยังติดขัดก่อนเดินต่อ',
  ];
  watchSignals = [
    'เด็กตอบ checkpoint ได้ดีขึ้นหรือไม่',
    'ช่วงต้นคาบยังเงียบเหมือนเดิมหรือไม่',
    'ห้องกลับมามีส่วนร่วมเร็วขึ้นหรือไม่',
  ];
  whyThisHelps = 'การเพิ่ม checkpoint และลดความเร็วช่วงต้นคาบช่วยให้ครูเห็นจุดสะดุดเร็วขึ้นและลดแรงกดดันที่สะสม';
} else if (policyLevel === 'WARNING' && recentNoAction) {
  teacherSummary = 'สัญญาณของห้องควรติดตามต่อ แต่ยังไม่ควรเร่งเพิ่มภาระการตอบสนองของครูมากเกินไป';
  situationHypothesis = 'ห้องมีแรงตึงระดับกลางต่อเนื่องและอาจต้องใช้การแทรกแซงที่เบาแต่สม่ำเสมอ';
  recommendedTeacherMove = 'เลือกการแทรกแซงสั้น ๆ เพียงหนึ่งอย่างที่ทำได้จริงในคาบถัดไป';
  studentMessageDraft = 'จากฟีดแบ็กของห้อง คาบถัดไปเราจะเริ่มด้วยช่วงเช็กความเข้าใจสั้น ๆ ก่อน เพื่อให้ทุกคนบอกได้ว่าตรงไหนยังติดอยู่';
  teacherActionPlan = [
    'เลือก 1 การเปลี่ยนแปลงสั้น ๆ ที่ทำได้จริงในคาบถัดไป',
    'เช็กความเข้าใจก่อนเดินเนื้อหาหลัก',
    'ดูผลตอบรับอีกครั้งหลังจบคาบ',
  ];
  watchSignals = [
    'การแทรกแซงสั้น ๆ ช่วยให้ห้องผ่อนลงหรือไม่',
    'เด็กตอบสนองดีขึ้นหลังมีช่วงเช็กความเข้าใจหรือไม่',
  ];
